insert into public.message_templates(type,name,tone,body_en,body_bn) values
('emi_due','EMI · Gentle',1,'Hello {{name}}, a gentle reminder that your {{scooter}} EMI of {{amount}} is due on {{date}}. Thank you — {{shop}}.','নমস্কার {{name}}, আপনার {{scooter}}-এর {{amount}} EMI {{date}} তারিখে জমা দেওয়ার কথা। ধন্যবাদ — {{shop}}।'),
('emi_due','EMI · Due today',2,'Hello {{name}}, your {{scooter}} EMI of {{amount}} is due today. Please let us know once paid. — {{shop}}','নমস্কার {{name}}, আপনার {{scooter}}-এর {{amount}} EMI আজ জমা দেওয়ার দিন। জমা হলে জানাবেন। — {{shop}}'),
('emi_due','EMI · Overdue 1',1,'Hello {{name}}, your EMI of {{amount}} for the {{scooter}} is still pending since {{date}}. Please let us know if you need assistance. — {{shop}}','নমস্কার {{name}}, {{scooter}}-এর {{amount}} EMI এখনও বাকি আছে ({{date}} থেকে)। সাহায্য লাগলে আমাদের জানান। — {{shop}}'),
('emi_due','EMI · Overdue 3',3,'Hello {{name}}, {{amount}} for your scooter EMI has been overdue since {{date}}. Please contact {{shop}} today so we can help.','নমস্কার {{name}}, আপনার স্কুটারের {{amount}} EMI {{date}} থেকে বকেয়া। সহায়তার জন্য আজই {{shop}}-এ যোগাযোগ করুন।'),
('emi_due','EMI · Overdue 7',4,'Hello {{name}}, a final follow-up from {{shop}}: your {{amount}} scooter EMI remains unpaid since {{date}}. Please call us to discuss.','নমস্কার {{name}}, {{shop}} থেকে শেষবার জানাচ্ছি: আপনার {{amount}} EMI {{date}} থেকে বাকি রয়েছে। কথা বলতে আমাদের ফোন করুন।'),
('service_due','Free service 1',1,'Hello {{name}}, your {{scooter}} is due for its 1st free service. Reply to book a convenient time. — {{shop}}','নমস্কার {{name}}, আপনার {{scooter}}-এর প্রথম ফ্রি সার্ভিসের সময় হয়েছে। সময় ঠিক করতে উত্তর দিন। — {{shop}}'),
('service_due','Free service 2',1,'Hello {{name}}, your {{scooter}} is due for its 2nd free service. Reply to book a convenient time. — {{shop}}','নমস্কার {{name}}, আপনার {{scooter}}-এর দ্বিতীয় ফ্রি সার্ভিসের সময় হয়েছে। সময় ঠিক করতে উত্তর দিন। — {{shop}}'),
('service_due','Free service 3',1,'Hello {{name}}, your {{scooter}} is due for its 3rd free service. Reply to book a convenient time. — {{shop}}','নমস্কার {{name}}, আপনার {{scooter}}-এর তৃতীয় ফ্রি সার্ভিসের সময় হয়েছে। সময় ঠিক করতে উত্তর দিন। — {{shop}}'),
('review_ask','Google review',1,'Hello {{name}}, we hope you are enjoying your {{scooter}}. Would you share a quick review? {{link}} — {{shop}}','নমস্কার {{name}}, আশা করি {{scooter}} ভালো লাগছে। আপনার মতামত এখানে জানালে খুশি হব: {{link}} — {{shop}}'),
('feedback_call','Feedback call',1,'Hello {{name}}, how has your {{scooter}} been performing? Please call us if you have any feedback. — {{shop}}','নমস্কার {{name}}, আপনার {{scooter}} কেমন চলছে? মতামত জানাতে আমাদের ফোন করুন। — {{shop}}'),
('delivery_anniversary','Anniversary wish',1,'Happy delivery anniversary, {{name}}! Wishing you many more happy rides on your {{scooter}}. — {{shop}}','ডেলিভারির বর্ষপূর্তির শুভেচ্ছা, {{name}}! {{scooter}} নিয়ে আরও আনন্দের যাত্রা হোক। — {{shop}}'),
('paid_service_nudge','Paid service reminder',1,'Hello {{name}}, it may be time for a check-up of your {{scooter}}. Reply to book a service at {{shop}}.','নমস্কার {{name}}, আপনার {{scooter}}-এর সার্ভিসের সময় হতে পারে। বুক করতে উত্তর দিন — {{shop}}')
